{
  "technical_and_design_decisions": [
    "Classloader isolation / custom classloader hierarchy will be implemented for module dependency resolution at runtime to avoid version conflicts (e.g., differing Spring Data versions).",
    "Spring Boot Profiles will be leveraged in the Admin application to select repository backing strategies, with an in-memory implementation for the 'local' profile.",
    "Containerization will be accomplished via Dockerfile integration into the Maven/Gradle build process, configured to publish images to DockerHub.",
    "Counter metrics will be exposed using Spring Boot Actuator and custom REST endpoints to provide data feeds for dashboard visualization."
  ],
  "assumptions": [
    "Development environment uses JDK 17+ and standard Spring Cloud Data / Stream source repository access.",
    "Credentials and permissions for publishing images to the designated DockerHub repository are provided.",
    "The screencast requires a functional firehose | counter stream setup, sample dashboard, recording software, and public video hosting access.",
    "All activities will be performed by a single developer handling design, implementation, testing, and demonstration tasks."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Binding Selection and Fallback Investigation (U1)",
      "activity_description": "Investigate mechanisms for dynamically including or excluding message bus binding JARs, and design the binding selection and fallback logic when no binder is explicitly configured.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Runtime Dependency Resolution Support (U2)",
      "activity_description": "Implement runtime module isolation and dependency resolution (such as custom classloading) to allow coexisting modules with conflicting JAR versions.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Docker Image Build and Publishing Automation (U3)",
      "activity_description": "Create Docker build scripts/Dockerfile for s-c-d and configure automated workflows to push incremental builds to DockerHub.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "SingleNode Stream & Job Undeploy Strategy Implementation (U5)",
      "activity_description": "Establish a consistent undeploy strategy across jobs and streams, and implement the undeploy lifecycle operation for the single JVM (SingleNode) target.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Admin Profile Support & Local Memory Repository (U6)",
      "activity_description": "Add Spring Profile support to the core Admin application and implement an in-memory repository strategy backing the 'local' profile.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Design Foundation for Porting XD Modules to s-c-s (U7)",
      "activity_description": "Conduct architectural design and establish base module patterns for migrating legacy Spring XD modules into Spring Cloud Stream modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Counter Metrics Endpoints Implementation (U8)",
      "activity_description": "Expose counter and metrics endpoints in the application to feed downstream monitoring dashboards for stream monitoring.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Firehose to Counter Screencast Production (U4)",
      "activity_description": "Set up and record a public screencast demonstrating the firehose | counter stream pipeline, developer workflow, and metrics dashboard.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing and Verification",
      "activity_description": "Perform end-to-end integration testing covering profile activation, undeploy scenarios on single JVM, binder resolution, and Docker image validation.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 20
  }
}
